<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue';
import type {BlackjackGame} from '@new-game/game-math';
import {DealerRig} from '../src/dealer-rig';
import {DEAL_STEP} from '../src/blackjack-dealing';
const posterUrl=ref('');const host=ref<HTMLElement>(),game=ref<BlackjackGame>('royal-blackjack'),time=ref(0),status=ref('Loading'),loop=ref(false);let rig:DealerRig|undefined,raf=0,started=0,generation=0;
const videoUrl=ref(''),recording=ref(false);let recorder:MediaRecorder|undefined;
async function load(){const gen=++generation;cancelAnimationFrame(raf);loop.value=false;posterUrl.value='';rig?.dispose();status.value='Loading';rig=new DealerRig(host.value!,game.value);await rig.load();if(gen!==generation)return;rig.start({id:1,kind:'deal',card:{rank:1,suit:0},target:{x:.5,y:.82,width:58/1280,height:82/500}});rig.render(time.value);status.value='Ready';}
function render(){rig?.render(Number(time.value));if(rig?.hands.length)status.value='Ready · pad error '+rig.hands[0].contactError().map(n=>(n*1000).toFixed(1)).join('/')+' mm';}
function tick(now:number){time.value=Math.round((now-started)%(DEAL_STEP+400));rig?.render(Math.min(time.value,DEAL_STEP),now);if(loop.value)raf=requestAnimationFrame(tick);}
function play(){loop.value=!loop.value;if(loop.value){started=performance.now();raf=requestAnimationFrame(tick);}else cancelAnimationFrame(raf);}
function closeup(){if(!rig)return;rig.camera.zoom=rig.camera.zoom===1?2.1:1;rig.camera.lookAt(0,rig.camera.zoom===1?1:1.43,.25);rig.camera.updateProjectionMatrix();render();}
function face(){if(!rig)return;rig.camera.zoom=5;rig.camera.lookAt(0,1.58,.05);rig.camera.updateProjectionMatrix();render();}
function hands(){if(!rig)return;rig.camera.zoom=5;rig.camera.lookAt(.18,1.17,.30);rig.camera.updateProjectionMatrix();render();}
function poster(){if(!rig)return;rig.rest();const hidden=rig.scene.children.filter(o=>o.type==='Mesh').map(o=>({o,visible:o.visible}));hidden.forEach(({o})=>o.visible=false);rig.renderer.render(rig.scene,rig.camera);posterUrl.value=rig.renderer.domElement.toDataURL('image/png');hidden.forEach(({o,visible})=>o.visible=visible);rig.start({id:1,kind:'deal',card:{rank:1,suit:0},target:{x:.5,y:.82,width:58/1280,height:82/500}});rig.render(Number(time.value));}
function record(){if(!rig||recording.value)return;recording.value=true;videoUrl.value='';const stream=rig.renderer.domElement.captureStream(30),chunks:Blob[]=[];recorder=new MediaRecorder(stream,{mimeType:'video/webm',videoBitsPerSecond:2000000});recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());recording.value=false;if(loop.value)play();const reader=new FileReader();reader.onload=()=>videoUrl.value=String(reader.result);reader.readAsDataURL(new Blob(chunks,{type:'video/webm'}));};if(!loop.value)play();recorder.start();setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();},6000);}
watch(game,load);onMounted(load);onBeforeUnmount(()=>{generation++;if(recorder?.state==='recording')recorder.stop();cancelAnimationFrame(raf);rig?.dispose();});
</script>
<template><main><h1>Dealer motion acceptance</h1><p>Local presentation fixture · no account, stake or credit action</p><nav><select v-model="game" aria-label="Dealer"><option value="royal-blackjack">Royal</option><option value="double-deck-blackjack">Double Deck</option><option value="european-blackjack">European</option></select><button @click="closeup">Close up</button><button @click="face">Face close up</button><button @click="hands">Hands close up</button><button @click="poster">Save poster</button><button :disabled="recording" @click="record">Record motion</button><button @click="play">{{loop?'Pause':'Play loop'}}</button><button v-for="n in [0,180,260,450,650,760,890,1120]" :key="n" @click="time=n;render()">{{n}} ms</button></nav><a v-if="posterUrl" :href="posterUrl" :download="game+'-poster.png'">Rendered dealer PNG</a><a v-if="videoUrl" :href="videoUrl" download="dealer-motion.webm">Recorded motion WebM</a><label>Timeline <input v-model="time" aria-label="Timeline" type="range" min="0" :max="DEAL_STEP" @input="render"/> {{time}} ms · {{status}}</label><div class="stage"><div class="felt"/><div ref="host" class="host"/></div></main></template>
<style>body{margin:0;background:#10101c;color:#e7e2d4;font:14px system-ui}main{padding:16px}h1{font-size:20px;margin:0}p{color:#a9a1bc}nav{display:flex;gap:8px;margin:12px 0}button,select{padding:8px;background:#29253e;color:white;border:1px solid #665678;border-radius:6px}label{display:flex;gap:12px;align-items:center}input{width:500px}.stage{width:1280px;height:500px;position:relative;background:radial-gradient(ellipse at top,#443454,#0d101f);overflow:hidden;margin-top:12px}.felt{position:absolute;inset:41% -5% -30%;border:7px solid #14131e;border-top:8px solid #a89060;border-radius:50% 50% 0 0/15% 15% 0 0;background:radial-gradient(ellipse at 50% 0%,#2e375e,#11182b 77%)}.host{position:absolute;inset:0}.host canvas{width:100%;height:100%}</style>
